var Account, Utilities, countCall;

Account = {
  get: function(callback) {
    return this.getApiKey(function(api_key) {
      var url;
      if (api_key !== '') {
        url = 'https://v1.tldrthis.com/tldr/api/account?api_key=' + api_key;
        return $.ajax({
          url: url,
          type: 'GET',
          dataType: 'json',
          jsonp: false,
          success: function(json) {
            return callback(json);
          },
          error: function() {
            return callback('none');
          }
        });
      } else {
        return callback('none');
      }
    });
  },
  setApiKey: function(api_key) {
    return chrome.storage.sync.set(
      {
        api_key: api_key
      },
      function() {
        return console.info('TLDR This extension successfully installed.');
      }
    );
  },
  getApiKey: function(fn) {
    return chrome.storage.sync.get(
      {
        api_key: false
      },
      function(value) {
        var api_key;
        if (value.api_key) {
          api_key = value.api_key;
        } else {
          api_key = '';
        }
        return fn(api_key);
      }
    );
  }
};

countCall = function() {
  return chrome.storage.sync.get(
    {
      calls_count: 0
    },
    function(value) {
      value.calls_count++;
      return chrome.storage.sync.set({
        calls_count: value.calls_count
      });
    }
  );
};

Utilities = {
  withoutSubDomain: function(domain) {
    var newdomain, subdomainsCount;
    subdomainsCount = (domain.match(/\./g) || []).length;
    if (subdomainsCount > 1) {
      newdomain = domain;
      newdomain = newdomain.substring(newdomain.indexOf('.') + 1);
      if (newdomain.length > 6) {
        return newdomain;
      } else {
        return false;
      }
    }
    return false;
  },
  numberWithCommas: function(x) {
    return x.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  },
  showDismissableTooltip: function(selector, title, duration) {
    if (selector.next('div.tooltip:visible').length) {
      return;
    }
    selector
      .tooltip({
        title: title
      })
      .tooltip('show');
    return setTimeout(function() {
      return selector.tooltip('destroy');
    }, duration);
  }
};
